#!/usr/bin/env node
/**
 * apply-pre-db-artifact-fixes.mjs
 *
 * Removes parser-artifact non-plant entries (corrupted/truncated genus names)
 * from data/pre-db.json and the related entries from data/lt-names.json.
 *
 * Source of truth: data/pre-db-artifact-fixes.json (generated by audit task #43).
 *
 * Usage:
 *   node scripts/apply-pre-db-artifact-fixes.mjs           # dry-run (default)
 *   node scripts/apply-pre-db-artifact-fixes.mjs --apply   # actually write files
 *
 * Side effects (with --apply):
 *   - Creates backups: pre-db.json.backup.<timestamp> + lt-names.json.backup.<timestamp>
 *   - Removes artifact keys from pre-db.json.genera
 *   - Removes related entries from lt-names.json.ltNames
 *   - Idempotent: safe to re-run; already-deleted entries are skipped.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_DIR = path.resolve(__dirname, '..', 'data');

const PRE_DB_PATH = path.join(DATA_DIR, 'pre-db.json');
const LT_NAMES_PATH = path.join(DATA_DIR, 'lt-names.json');
const FIXES_PATH = path.join(DATA_DIR, 'pre-db-artifact-fixes.json');

const APPLY = process.argv.includes('--apply');

function readJson(p) {
  return JSON.parse(fs.readFileSync(p, 'utf8'));
}
function writeJson(p, obj) {
  fs.writeFileSync(p, JSON.stringify(obj, null, 2));
}
function backupFile(p) {
  const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
  const dst = `${p}.backup.${ts}`;
  fs.copyFileSync(p, dst);
  return dst;
}

function main() {
  console.log(`Mode: ${APPLY ? 'APPLY (writing changes)' : 'DRY-RUN (no writes)'}`);
  console.log();

  const fixes = readJson(FIXES_PATH);
  const preDb = readJson(PRE_DB_PATH);
  const ltDb = readJson(LT_NAMES_PATH);
  const ltNames = ltDb.ltNames || ltDb;

  const artifactKeys = fixes.artifacts || Object.keys(fixes.fixes || {});

  let preDbDeleted = 0;
  let preDbAlreadyGone = 0;
  let ltDeleted = 0;
  let ltAlreadyGone = 0;

  for (const genusKey of artifactKeys) {
    const fix = fixes.fixes[genusKey];
    if (!fix) {
      console.warn(`  ! No fix entry for ${genusKey} — skipping`);
      continue;
    }

    // pre-db.json removal
    if (preDb.genera[genusKey]) {
      console.log(`  - pre-db.genera.${genusKey} → DELETE (${fix.realGenus})`);
      delete preDb.genera[genusKey];
      preDbDeleted++;
    } else {
      console.log(`  · pre-db.genera.${genusKey} already absent`);
      preDbAlreadyGone++;
    }

    // lt-names.json removal
    const ltKey = fix.deleteFromLtNames;
    if (ltKey) {
      if (ltNames[ltKey]) {
        console.log(`  - lt-names.ltNames.${ltKey} → DELETE (was: ${fix.wrongLtNameAttribution})`);
        delete ltNames[ltKey];
        ltDeleted++;
      } else {
        console.log(`  · lt-names.ltNames.${ltKey} already absent`);
        ltAlreadyGone++;
      }
    }
  }

  console.log();
  console.log('Summary:');
  console.log(`  pre-db.json:   ${preDbDeleted} deleted, ${preDbAlreadyGone} already gone`);
  console.log(`  lt-names.json: ${ltDeleted} deleted, ${ltAlreadyGone} already gone`);

  if (!APPLY) {
    console.log();
    console.log('Dry-run complete. Re-run with --apply to write changes.');
    return;
  }

  if (preDbDeleted === 0 && ltDeleted === 0) {
    console.log();
    console.log('Nothing to write — all artifacts already removed.');
    return;
  }

  console.log();
  console.log('Backing up files...');
  if (preDbDeleted > 0) {
    const b = backupFile(PRE_DB_PATH);
    console.log('  pre-db backup:   ' + path.basename(b));
    // Update stats counter on pre-db if present
    if (preDb.stats && typeof preDb.stats.genusCount === 'number') {
      preDb.stats.genusCount = Object.keys(preDb.genera).length;
    }
    preDb._lastArtifactFixApplied = {
      at: new Date().toISOString(),
      taskRef: fixes.taskRef || '#43',
      removed: artifactKeys.filter(k => fixes.fixes[k]?.deleteFromPreDb),
    };
    writeJson(PRE_DB_PATH, preDb);
    console.log('  pre-db.json written.');
  }
  if (ltDeleted > 0) {
    const b = backupFile(LT_NAMES_PATH);
    console.log('  lt-names backup: ' + path.basename(b));
    // Ensure stats are consistent if present
    if (ltDb.stats && typeof ltDb.stats.totalEntries === 'number') {
      ltDb.stats.totalEntries = Object.keys(ltNames).length;
    }
    ltDb._lastArtifactFixApplied = {
      at: new Date().toISOString(),
      taskRef: fixes.taskRef || '#43',
      removed: artifactKeys
        .map(k => fixes.fixes[k]?.deleteFromLtNames)
        .filter(Boolean),
    };
    writeJson(LT_NAMES_PATH, ltDb);
    console.log('  lt-names.json written.');
  }

  console.log();
  console.log('Done.');
}

main();
